PAGE = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>Artifact Graph</title><script src="https://unpkg.com/cytoscape@3.30.4/dist/cytoscape.min.js"></script>
<style>
html,body{height:100%;margin:0;font:14px system-ui;background:#0d1117;color:#e6edf3}header{min-height:58px;display:flex;align-items:center;gap:8px;padding:8px 16px;border-bottom:1px solid #30363d;box-sizing:border-box;flex-wrap:wrap}input,select{padding:8px 10px;border:1px solid #30363d;border-radius:7px;background:#161b22;color:white}input{width:260px}button{padding:8px 11px;background:#238636;border:0;border-radius:7px;color:white;cursor:pointer}button.secondary{background:#30363d}.graph{height:calc(100% - 75px);position:relative}.columns{position:absolute;top:10px;left:0;right:0;display:grid;grid-template-columns:34% 33% 33%;z-index:1;pointer-events:none;color:#8b949e;text-align:center;font-size:12px;text-transform:uppercase;letter-spacing:.08em}.columns span{padding-bottom:8px;border-bottom:1px solid #21262d}.legend{position:absolute;left:16px;bottom:12px;z-index:2;color:#9da7b3;background:#161b22dd;border:1px solid #30363d;border-radius:7px;padding:7px 10px;font-size:12px;display:flex;gap:12px;flex-wrap:wrap;max-width:70%}.legend i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}.legend .square{border-radius:1px}.legend .pale-yellow{background:#f2d675}.legend .pale-red{background:#e99a95}.legend .pale-green{background:#9fd8ad}.legend .pale-gray{background:#7d8590}.legend .blue{background:#2f81f7}.legend .green{background:#2ea043}.legend .teal{background:#00b3a4}#cy{height:100%}#detail,#diffPanel{position:absolute;right:16px;top:92px;width:360px;max-height:72%;overflow:auto;background:#161b22;border:1px solid #30363d;border-radius:8px;padding:14px;display:none;z-index:3;box-shadow:0 8px 30px #0008}#diffPanel{left:16px;right:auto;width:300px}#hover{position:fixed;display:none;z-index:4;pointer-events:none;max-width:340px;background:#161b22f5;border:1px solid #484f58;border-radius:7px;padding:9px 11px;box-shadow:0 6px 20px #0009;font-size:12px}.hover-title{font-weight:700;margin-bottom:4px}.hover-row{color:#c9d1d9;margin-top:3px}.detail-title{font-size:17px;margin-bottom:8px}.detail-label{color:#8b949e;margin-top:12px;font-size:12px;text-transform:uppercase}.detail-list{margin:6px 0;padding-left:20px}pre{white-space:pre-wrap;word-break:break-word;color:#9da7b3}a{color:#58a6ff}.status{margin-left:auto;color:#9da7b3}.status.degraded{color:#f2d675;font-weight:700}.hint{font-size:12px;color:#8b949e}
</style></head><body>
<header><strong>Artifact Graph</strong><input id="q" placeholder="Поиск по имени репозитория">
<select id="bbProject"><option value="">Все проекты BB</option></select><select id="tcProject"><option value="">Все проекты TC</option></select>
<select id="statusFilter"><option value="">Любой статус</option><option>SUCCESS</option><option>FAILURE</option><option>RUNNING</option><option>QUEUED</option></select>
<select id="engineFilter"><option value="">Docker и Podman</option><option value="docker">Docker</option><option value="podman">Podman</option></select>
<select id="imageFilter"><option value="">С образом / без</option><option value="true">Есть image</option><option value="false">Нет image</option></select>
<select id="sbomFilter"><option value="">С SBOM / без</option><option value="true">Есть SBOM</option><option value="false">Нет SBOM</option></select>
<select id="targetOnly"><option value="">Все ветки</option><option value="true">Только push/SBOM</option></select>
<select id="sinceDays"><option value="0">За всё время</option><option value="1">24 часа</option><option value="7">7 дней</option><option value="30">30 дней</option></select>
<button onclick="load()">Применить</button><button class="secondary" onclick="resetFilters()">Сбросить</button><button class="secondary" onclick="expandAll()">Развернуть всё</button><button onclick="refresh()">Обновить</button><select id="snapshotBefore" title="Предыдущий снимок"></select><select id="snapshotAfter" title="Новый снимок"></select><button class="secondary" onclick="compareSnapshots()">Сравнить</button><button class="secondary" onclick="clearDiff()">Убрать diff</button><span class="status" id="status"></span></header>
<div class="graph"><div class="columns"><span>Bitbucket: проекты / репозитории</span><span>TeamCity: проекты / build configurations</span><span>Билды TC</span></div><div class="legend"><span><i class="pale-yellow"></i>в работе / очереди</span><span><i class="pale-red"></i>упал</span><span><i class="pale-green"></i>успех / активен</span><span><i class="pale-gray square"></i>неактивен</span><span><i class="blue"></i>SBOM</span><span><i class="green"></i>push</span><span><i class="teal"></i>SBOM + push / ветка с результатом</span></div><div id="cy"></div></div><div id="detail"></div><div id="diffPanel"></div><div id="hover"></div>
<script>
const colors={};
const UI_KEY='artifactGraph.ui.v1',collapsible=new Set(['bb_project','repository','tc_project','build_configuration']);let cy,baseGraph,uiState=readUiState(),collapsed=new Set(uiState.collapsed||[]),saveTimer;
function readUiState(){try{return JSON.parse(localStorage.getItem(UI_KEY)||'{}')}catch(_){return {}}}function saveUiState(){if(!cy)return;const state={zoom:cy.zoom(),pan:cy.pan(),collapsed:[...collapsed]};try{localStorage.setItem(UI_KEY,JSON.stringify(state))}catch(_){}}function scheduleUiSave(){clearTimeout(saveTimer);saveTimer=setTimeout(saveUiState,150)}
function params(){const p=new URLSearchParams(),map={q:'q',bb_project:'bbProject',tc_project:'tcProject',status_filter:'statusFilter',engine_filter:'engineFilter',has_image:'imageFilter',has_sbom:'sbomFilter',target_only:'targetOnly',since_days:'sinceDays'};for(const [key,id] of Object.entries(map)){const value=document.getElementById(id).value;if(value&&!(key==='since_days'&&value==='0'))p.set(key,value)}return p}
async function init(){baseGraph=await fetch('/api/graph').then(check);fillOptions('bbProject',baseGraph.nodes.filter(n=>n.kind==='bb_project').map(n=>n.label));fillOptions('tcProject',baseGraph.nodes.filter(n=>n.kind==='tc_project').map(n=>n.label));render(baseGraph);await loadSnapshots();status()}
function fillOptions(id,values){const select=document.getElementById(id);for(const value of [...new Set(values)].sort())select.add(new Option(value,value))}
async function load(){const g=await fetch('/api/graph?'+params()).then(check);render(g);status()}
function render(g){hideHover();const viewport=cy?{zoom:cy.zoom(),pan:cy.pan()}:(uiState.zoom&&uiState.pan?{zoom:uiState.zoom,pan:uiState.pan}:null);const els=[...g.nodes.map(n=>({data:n,position:g.positions[n.id]})),...g.edges.map((e,i)=>({data:{id:'e'+i,...e,label:e.relation}}))];if(cy)cy.destroy();cy=cytoscape({container:document.getElementById('cy'),elements:els,style:[
{selector:'node',style:{'background-color':e=>colors[e.data('kind')]||'#9fd8ad','label':'data(label)','color':'#e6edf3','font-size':11,'text-valign':'bottom','text-margin-y':7,'width':32,'height':32}},
{selector:'node[kind = "bb_project"]',style:{'shape':'ellipse','width':18,'height':18,'border-width':4,'border-color':'#9fd8ad'}},{selector:'node[kind = "repository"]',style:{'shape':'round-rectangle','width':38,'height':11}},{selector:'node[kind = "tc_project"]',style:{'shape':'triangle','width':36,'height':36}},{selector:'node[kind = "build_configuration"]',style:{'shape':'rectangle','width':32,'height':32}},{selector:'node[kind = "build"]',style:{'shape':'ellipse','width':32,'height':32}},
{selector:'node[?active][?hasTargetOutput]',style:{'background-color':'#00b3a4','border-color':'#00b3a4'}},{selector:'node[kind = "bb_project"][!active],node[kind = "repository"][!active],node[kind = "tc_project"][!active],node[kind = "build_configuration"][!active]',style:{'background-color':'#7d8590','border-color':'#7d8590'}},
{selector:'node[kind = "build"][status = "SUCCESS"]',style:{'background-color':'#9fd8ad'}},{selector:'node[kind = "build"][status = "FAILURE"],node[kind = "build"][status = "ERROR"]',style:{'background-color':'#e99a95'}},{selector:'node[kind = "build"][state = "running"],node[kind = "build"][state = "queued"]',style:{'background-color':'#f2d675'}},
{selector:'node[kind = "build"][?hasSbom][!hasImagePush]',style:{'background-color':'#2f81f7'}},{selector:'node[kind = "build"][?hasImagePush][!hasSbom]',style:{'background-color':'#2ea043'}},{selector:'node[kind = "build"][?hasSbom][?hasImagePush]',style:{'background-color':'#00b3a4'}},
{selector:'edge',style:{'width':1.5,'line-color':'#484f58','target-arrow-color':'#484f58','target-arrow-shape':'triangle','curve-style':'straight','label':'data(label)','font-size':8,'color':'#8b949e','text-background-color':'#0d1117','text-background-opacity':1}},
{selector:'edge.dependency',style:{'line-style':'dashed','curve-style':'taxi'}},{selector:':selected',style:{'border-width':3,'border-color':'#fff'}},{selector:'node[?stale]',style:{'border-width':4,'border-style':'dashed','border-color':'#f2d675'}},{selector:'.diff-added',style:{'border-width':5,'border-color':'#3fb950'}},{selector:'.diff-changed',style:{'border-width':5,'border-color':'#d29922'}}],layout:{name:'preset',fit:!viewport,padding:70},minZoom:.2,maxZoom:3,wheelSensitivity:.18});if(viewport){cy.zoom(viewport.zoom);cy.pan(viewport.pan)}collapsed=new Set([...collapsed].filter(id=>cy.getElementById(id).length));cy.on('pan zoom',scheduleUiSave);cy.on('tap','node',e=>showDetail(e.target.data()));cy.on('tap',e=>{if(e.target===cy)closeDetail()});cy.on('dbltap','node',e=>{if(collapsible.has(e.target.data('kind')))toggleCollapse(e.target.id())});cy.on('mouseover','node[kind = "build"]',e=>showHover(e.target.data(),e.originalEvent));cy.on('mousemove','node[kind = "build"]',e=>moveHover(e.originalEvent));cy.on('mouseout','node[kind = "build"]',hideHover);applyCollapsed()}
async function loadSnapshots(){const rows=await fetch('/api/snapshots?limit=50').then(check),before=document.getElementById('snapshotBefore'),after=document.getElementById('snapshotAfter');before.innerHTML='';after.innerHTML='';for(const row of rows){const label='#'+row.id+' · '+new Date(row.createdAt).toLocaleString();before.add(new Option(label,row.id));after.add(new Option(label,row.id))}if(rows.length>1)before.value=rows[1].id;if(rows.length)after.value=rows[0].id}
async function compareSnapshots(){const before=document.getElementById('snapshotBefore').value,after=document.getElementById('snapshotAfter').value;if(!before||!after)return;const d=await fetch('/api/snapshots/'+before+'/diff/'+after).then(check);cy.elements().removeClass('diff-added diff-changed');for(const id of d.nodes.added)cy.getElementById(id).addClass('diff-added');for(const id of d.nodes.changed)cy.getElementById(id).addClass('diff-changed');const panel=document.getElementById('diffPanel');panel.style.display='block';panel.innerHTML='<div class="detail-title">Изменения #'+esc(before)+' → #'+esc(after)+'</div>'+field('Добавлено',d.nodes.added.length)+field('Изменено',d.nodes.changed.length)+field('Удалено',d.nodes.removed.length)+(d.outputChanges.length?list('Изменения push / SBOM',d.outputChanges.map(x=>esc(x.id))):'')+(d.details.removed.length?list('Удалённые сущности',d.details.removed.map(x=>esc(x.label||x.id))):'')}
function clearDiff(){if(cy)cy.elements().removeClass('diff-added diff-changed');const panel=document.getElementById('diffPanel');panel.style.display='none';panel.innerHTML=''}
function descendants(root){const allowed=new Set(['contains','maps_to','ran_as']);const found=new Set(),queue=[root];while(queue.length){const id=queue.shift();cy.edges(`[source = "${id}"]`).forEach(edge=>{if(allowed.has(edge.data('relation'))&&!found.has(edge.data('target'))){found.add(edge.data('target'));queue.push(edge.data('target'))}})}return found}
function toggleCollapse(id){collapsed.has(id)?collapsed.delete(id):collapsed.add(id);applyCollapsed();saveUiState()}
function applyCollapsed(){cy.nodes().show();for(const id of collapsed)for(const child of descendants(id))cy.getElementById(child).hide()}
function expandAll(){collapsed.clear();if(cy)cy.elements().show();saveUiState()}
function resetFilters(){for(const id of ['q','bbProject','tcProject','statusFilter','engineFilter','imageFilter','sbomFilter','targetOnly'])document.getElementById(id).value='';document.getElementById('sinceDays').value='0';collapsed.clear();uiState={};try{localStorage.removeItem(UI_KEY)}catch(_){};load()}
function showDetail(d){const box=document.getElementById('detail');box.style.display='block';let html='<div class="detail-title">'+esc(d.label)+'</div>';
if(d.stale)html+=field('Устаревшие данные',esc(d.staleReason||'источник временно недоступен')+(d.staleSince?' · '+esc(d.staleSince):''));if(d.webUrl||d.url)html+='<div>'+safeLink(d.webUrl||d.url,'Открыть источник')+'</div>';if(d.visualReason)html+=field('Причина цвета',esc(d.visualReason));if(d.status||d.state)html+=field('Статус',esc(d.state||d.status)+(d.statusText?' · '+esc(d.statusText):''));if(d.finishDate)html+=field('Завершён',esc(d.finishDate));if(d.digest)html+=field('Digest','<code>'+esc(d.digest)+'</code>');if(d.manifestUrl)html+='<div>'+safeLink(d.manifestUrl,'Открыть manifest')+'</div>';
if(d.pushedImages?.length)html+=list('Выполненные push',d.pushedImages.map(x=>'<b>'+esc(x.engine+' push '+x.image)+'</b>'+(x.digest?'<br><code>'+esc(x.digest)+'</code>':'')+'<br><span class="hint">Подтверждено по TeamCity build log</span>'));if(d.sbomArtifacts?.length)html+=list('SBOM артефакты',d.sbomArtifacts.map(x=>safeLink(x.url,x.path)+'<br><span class="hint">Найден как артефакт: '+esc(x.artifactRule||'**/sbom.json => artifacts')+(x.sbomStatus?' · '+esc(x.sbomStatus):'')+'</span>'+(x.relatedImages?.length?'<br><span class="hint">image: '+esc(x.relatedImages.join(', '))+'</span>':'')));if(d.evidencePaths?.length)html+=list('Источники',d.evidencePaths.map(esc));if(collapsible.has(d.kind))html+='<button id="collapseButton" class="secondary">Свернуть / развернуть ветку</button>';html+='<details><summary>Технические данные</summary><pre>'+esc(JSON.stringify(d,null,2))+'</pre></details>';box.innerHTML=html;const button=document.getElementById('collapseButton');if(button)button.onclick=()=>toggleCollapse(d.id)}
function closeDetail(){const box=document.getElementById('detail');box.style.display='none';box.innerHTML='';if(cy)cy.$(':selected').unselect()}
function showHover(d,event){const box=document.getElementById('hover');const pushes=d.pushedImages||[],sboms=d.sbomArtifacts||[];let html='<div class="hover-title">'+esc(d.label)+' · '+esc(d.state||d.status||'')+'</div>';if(pushes.length)html+='<div class="hover-row">push: '+esc(pushes.map(x=>x.image+(x.digest?' · '+x.digest.slice(0,19)+'…':'')).join(', '))+'</div>';if(sboms.length)html+='<div class="hover-row">SBOM: '+esc(sboms.map(x=>x.path+' · '+(x.sbomStatus||'найден')).join(', '))+'</div>';if(!pushes.length&&!sboms.length)html+='<div class="hover-row">Целевых артефактов нет</div>';box.innerHTML=html;box.style.display='block';moveHover(event)}function moveHover(event){if(!event)return;const box=document.getElementById('hover');box.style.left=Math.min(event.clientX+14,window.innerWidth-box.offsetWidth-10)+'px';box.style.top=Math.min(event.clientY+14,window.innerHeight-box.offsetHeight-10)+'px'}function hideHover(){document.getElementById('hover').style.display='none'}
function field(label,value){return '<div class="detail-label">'+esc(label)+'</div><div>'+value+'</div>'}function list(label,items){return '<div class="detail-label">'+esc(label)+'</div><ul class="detail-list">'+items.map(x=>'<li>'+x+'</li>').join('')+'</ul>'}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function safeLink(url,label){return /^https?:\/\//.test(url||'')?'<a href="'+esc(url)+'" target="_blank" rel="noopener">'+esc(label)+'</a>':esc(label)}async function check(response){if(!response.ok)throw new Error(await response.text());return response.json()}
let lastScanFinished='';async function status(){const s=await fetch('/api/status').then(check);const finished=s.lastScan?.finishedAt||'',box=document.getElementById('status');box.textContent=s.mode+' · '+(s.lastScan?.message||'нет скана')+(finished?' · '+finished:'');box.classList.toggle('degraded',s.lastScan?.status==='degraded');const changed=lastScanFinished&&finished&&finished!==lastScanFinished&&['success','degraded'].includes(s.lastScan.status);lastScanFinished=finished;if(changed)await load();return s}async function refresh(){await fetch('/api/refresh',{method:'POST'}).then(check);setTimeout(status,1500)}document.getElementById('q').addEventListener('keydown',e=>{if(e.key==='Enter')load()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});document.querySelector('header').addEventListener('click',closeDetail);init();setInterval(status,60000);
</script></body></html>'''
